            + 0.40 * torch.kron(Z, I2)
            + 0.40 * torch.kron(I2, Z)
            - 0.20 * torch.kron(Z, Z)
            - 0.20 * torch.kron(X, X)
            - 0.05 * torch.kron(Y, Y)
